mapper.select:
with t as( select sum(submit_total_num) as submit_total_num,report_main_id from ${submitTable} a where a.status = 4 and a.submit_num > 0 and a.delete_flag = false GROUP BY a.report_main_id ), t1 as( select a.*, a.primary_key as primaryKeyValue, COALESCE(t.submit_total_num,0) as submit_total_num, c.report_main_id as batchNo from ${tableName} a LEFT JOIN t on a.report_main_id = t.report_main_id LEFT JOIN (select DISTINCT report_main_id from ${submitTable} where submit_num > 0) c on c.report_main_id = a.report_main_id where a.enterprise_code = #{enterpriseCode} and a.delete_flag = false
${dataScopeParams.dataScope}
and a.buss_number like concat('%',#{data.bussNumber}, '%')
and ( a.procedure_name like concat('%',#{data.name}, '%') or a.product_or_part_name like concat('%',#{data.name}, '%') )
and COALESCE(a.related_name,'车间') like concat('%',#{data.relatedName}, '%')
and a.model like concat('%',#{data.model}, '%')
and a.un_pass_deal_conclusion = #{data.unPassedDeal}
AND a.inspect_user_code IN
#{userCode}
and ${dynamicTableNameProxy.getXiHangPartQuery("a.Product_Or_Part_Code","xihang",data.partUnityNo)}
and ${dynamicTableNameProxy.getProductPartSearchObj("a.product_or_part_code",data.searchName)}
AND a.create_time >= #{data.beginDate}
AND a.create_time <= #{data.endDate}
AND a.inspect_origin_type = #{data.originType}
order by MAX(a.create_time) OVER (PARTITION BY a.main_id) DESC, a.main_id, a.create_time desc ) select * from( select t1.* ,a.check_items from t1 ,${inspectIntoReportTable} a where t1.report_main_id = a.primary_key and t1.inspect_origin_type = 3 union ALL select t1.* ,a.check_items from t1 ,${inspectProcessReportTable} a where t1.report_main_id = a.primary_key and t1.inspect_origin_type = 1 union ALL select t1.* ,a.check_items from t1 ,${inspectFinishReportTable} a where t1.report_main_id = a.primary_key and t1.inspect_origin_type = 2 ) tt order by tt.create_time desc
